const dados = $input.first().json;

function limpo(v) {
  return (v === undefined || v === null) ? '' : String(v).trim();
}

// Telefone: guarda só os dígitos (phone_digits) e uma versão formatada (phone),
// no mesmo padrão que o app usa quando o planejador cadastra o lead na mão.
const digitos = limpo(dados.telefone).replace(/\D/g, '');
const semPais = digitos.startsWith('55') && digitos.length > 11 ? digitos.slice(2) : digitos;

let telefoneFormatado = limpo(dados.telefone);
if (semPais.length === 11) {
  telefoneFormatado = `(${semPais.slice(0,2)}) ${semPais.slice(2,7)}-${semPais.slice(7)}`;
} else if (semPais.length === 10) {
  telefoneFormatado = `(${semPais.slice(0,2)}) ${semPais.slice(2,6)}-${semPais.slice(6)}`;
}

// As respostas 2, 4 e 5 do questionário viram o texto de observações do lead.
const linhas = [];
if (limpo(dados.ocupacao)) linhas.push(`Ocupação: ${limpo(dados.ocupacao)}`);
if (limpo(dados.faixa_renda)) linhas.push(`Faixa de renda informada: ${limpo(dados.faixa_renda)}`);
if (limpo(dados.decisoes_financeiras)) linhas.push(`Decisões financeiras: ${limpo(dados.decisoes_financeiras)}`);
if (limpo(dados.momento_financeiro)) linhas.push(`Momento financeiro: ${limpo(dados.momento_financeiro)}`);
linhas.push('');
linhas.push('Respondido pela assistente da Eleva no WhatsApp (landing page).');

// Renda: aceita número puro ou texto com R$/pontuação brasileira.
const rendaBruta = limpo(dados.renda_estimada).replace(/[^0-9,.-]/g, '').replace(/\./g, '').replace(',', '.');
const renda = Number(rendaBruta);

return [{ json: {
  name: limpo(dados.nome),
  phone: telefoneFormatado,
  phone_digits: semPais,
  notes: linhas.join('\n'),
  estimated_income: Number.isFinite(renda) && renda > 0 ? renda : 0
} }];

const rows = $input.all().map(i => i.json)
  .filter(r => Object.values(r).some(v => v !== null && v !== undefined));

if (rows.length === 0 || !rows[0].id) {
  return [{ json: {
    cadastrado: false,
    mensagem: 'Não foi possível registrar o lead. Não confirme o cadastro para a pessoa.'
  } }];
}

const row = rows[0];
return [{ json: {
  cadastrado: true,
  lead_id: row.id,
  nome: row.name,
  mensagem: 'Lead registrado com sucesso na etapa Lead do CRM da Eleva.'
} }];

